<?php
session_start();
if (($_SESSION['status'] ?? '') !== 'login' || !in_array($_SESSION['role'] ?? '', ['Admin', 'BK', 'Kepsek'], true)) {
    header('location:index.php');
    exit();
}
include 'koneksi.php';

$pesan = $_SESSION['pesan_verifikasi'] ?? '';
$status = $_SESSION['status_verifikasi'] ?? '';
unset($_SESSION['pesan_verifikasi'], $_SESSION['status_verifikasi']);

$filter = $_GET['status'] ?? 'pending';
$filter_valid = ['pending', 'disetujui', 'ditolak', 'semua'];
if (!in_array($filter, $filter_valid, true)) $filter = 'pending';
$where = $filter === 'semua' ? '' : "WHERE lp.status_verifikasi = '" . mysqli_real_escape_string($koneksi, $filter) . "'";
$laporan = mysqli_query($koneksi, "SELECT lp.*, s.nama_siswa, s.nis, s.kelas, u.nama_lengkap AS nama_pelapor, v.nama_lengkap AS nama_verifikator
    FROM laporan_prilaku lp
    JOIN siswa s ON s.id_siswa = lp.id_siswa
    LEFT JOIN users u ON u.id_user = lp.id_user
    LEFT JOIN users v ON v.id_user = lp.id_verifikator
    $where ORDER BY lp.id_laporan DESC");
$daftar_laporan = [];
if ($laporan) {
    while ($row = mysqli_fetch_assoc($laporan)) $daftar_laporan[] = $row;
}
?>
