<?php if ($daftar_laporan): foreach ($daftar_laporan as $row): $is_reward=$row['label_prediksi']==='Reward'; $is_pending=$row['status_verifikasi']==='pending'; $status_class=$is_pending?'bg-warning-subtle text-warning-emphasis':($row['status_verifikasi']==='disetujui'?'bg-success-subtle text-success':'bg-danger-subtle text-danger'); ?>
