<div class="mobile-view"><div class="d-flex justify-content-between gap-2"><div><span class="meta">NIS <?= htmlspecialchars($row['nis']) ?> · <?= htmlspecialchars($row['kelas']) ?></span><h6 class="fw-bold text-dark mb-1 mt-1" style="font-size:15px"><?= htmlspecialchars($row['nama_siswa']) ?></h6><span class="meta">Pelapor: <?= htmlspecialchars($row['nama_pelapor'] ?? '-') ?></span></div><span class="status-pill <?= $status_class ?> align-self-start"><?= strtoupper($row['status_verifikasi']) ?></span></div><div class="action-area"><div class="report-text mb-2">“<?= htmlspecialchars($row['teks_laporan']) ?>”</div><?php if (!empty($row['foto'])): ?><button type="button" class="btn p-0 border-0 bg-transparent mb-2 btn-zoom-foto" data-foto="<?= htmlspecialchars($row['foto'], ENT_QUOTES) ?>" data-nama="<?= htmlspecialchars($row['nama_siswa'], ENT_QUOTES) ?>"><img src="<?= htmlspecialchars($row['foto']) ?>" class="foto-bukti-thumb" alt="Foto bukti <?= htmlspecialchars($row['nama_siswa']) ?>"><span class="meta ms-1">Ketuk foto untuk perbesar</span></button><?php endif; ?><div class="d-flex justify-content-between align-items-center"><span class="badge-poin <?= $is_reward?'bg-success-subtle text-success':'bg-danger-subtle text-danger' ?>"><i class="bi <?= $is_reward?'bi-award-fill':'bi-exclamation-triangle-fill' ?>"></i><?= $is_reward?'+':'-' ?><?= (int)$row['poin_didapat'] ?> Poin</span><span class="meta"><?= date('d-m-Y H:i',strtotime($row['tgl_input'])) ?></span></div><?php if ($is_pending): ?><form method="post" action="proses_verifikasi_laporan.php" class="mt-3"><input type="hidden" name="id_laporan" value="<?= (int)$row['id_laporan'] ?>"><input name="catatan_verifikasi" class="form-control form-control-sm mb-2" placeholder="Catatan verifikasi (opsional)"><div class="d-flex gap-2"><button name="aksi" value="disetujui" class="btn btn-sm btn-success rounded-pill flex-fill"><i class="bi bi-check-lg"></i> Setujui</button><button name="aksi" value="ditolak" class="btn btn-sm btn-outline-danger rounded-pill flex-fill"><i class="bi bi-x-lg"></i> Tolak</button></div></form><?php else: ?><div class="meta mt-2">Catatan: <?= htmlspecialchars($row['catatan_verifikasi'] ?: '-') ?></div><?php endif; ?></div></div>
