</main><div class="modal fade" id="modalZoomFoto" tabindex="-1"><div class="modal-dialog modal-dialog-centered modal-lg"><div class="modal-content border-0"><div class="modal-header py-2"><h6 class="modal-title fw-bold"><i class="bi bi-image me-1"></i>Foto Bukti: <span id="namaFotoZoom"></span></h6><div class="btn-group btn-group-sm me-2"><button type="button" class="btn btn-outline-secondary" id="zoomOut" title="Perkecil"><i class="bi bi-dash-lg"></i></button><button type="button" class="btn btn-outline-secondary" id="zoomReset" title="Ukuran normal">100%</button><button type="button" class="btn btn-outline-secondary" id="zoomIn" title="Perbesar"><i class="bi bi-plus-lg"></i></button></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body p-0"><div class="zoom-stage" id="zoomStage"><img id="fotoZoom" src="" alt="Foto bukti diperbesar"></div></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><script>const modalZoom=new bootstrap.Modal(document.getElementById('modalZoomFoto')),fotoZoom=document.getElementById('fotoZoom'),namaFotoZoom=document.getElementById('namaFotoZoom');let skala=1;function aturZoom(nilai){skala=Math.min(3,Math.max(.5,nilai));fotoZoom.style.transform='scale('+skala+')';document.getElementById('zoomReset').textContent=Math.round(skala*100)+'%'}document.querySelectorAll('.btn-zoom-foto').forEach(el=>el.addEventListener('click',()=>{fotoZoom.src=el.dataset.foto;namaFotoZoom.textContent=el.dataset.nama;aturZoom(1);modalZoom.show()}));document.getElementById('zoomIn').addEventListener('click',()=>aturZoom(skala+.25));document.getElementById('zoomOut').addEventListener('click',()=>aturZoom(skala-.25));document.getElementById('zoomReset').addEventListener('click',()=>aturZoom(1));document.getElementById('zoomStage').addEventListener('wheel',e=>{e.preventDefault();aturZoom(skala+(e.deltaY<0?.1:-.1))},{passive:false});</script></body></html>
